snapshot.chatListCss:
/* Puff · 消息列表完整默认
   作用于即时消息列表（非线下入口）。变量 + 行内各块类名。
   只想改顶栏 / 表体 / 行样式时，用「短模板」更省事。 */

/* ========== A. 变量 ========== */
.chat-app {
  --dress-list-sheet-radius: 20px;
  --dress-list-row-pad-y: 12px;
  --dress-list-row-pad-x: 14px;
  --dress-list-preview-size: 11px;
  --dress-list-name-size: 0.9375rem;
  --dress-list-unread-bg: var(--ink);
  --dress-list-unread-fg: #fff;

  /* 灰白主题 */
  --dress-page-bg: #f7f7f8;
  --dress-head-bg: #f7f7f8;
  --dress-sheet-bg: #ffffff;
  --dress-row-bg: #ffffff;
  --dress-title-fg: #8a8f98;
  --dress-name-fg: #4a4f57;
  --dress-preview-fg: #9aa0a8;
  --dress-ava-bg: #e6e7ea;
  --dress-ava-ring: #ffffff;

  /* 三个圆形头像图片 */
  --dress-ava-img-1: url("https://imgbed.heliar.top/i/f_N1MLsZvx6_upRG_IMG_2174.jpeg");
  --dress-ava-img-2: url("https://imgbed.heliar.top/i/LF2hMGQ-9UyAstC7_IMG_2173.jpeg");
  --dress-ava-img-3: url("https://imgbed.heliar.top/i/dEzGcMNyA5VSytgm_IMG_2175.jpeg");
}

html[data-theme="dark"] .chat-app {
  --dress-list-unread-bg: #f0f0f0;
  --dress-list-unread-fg: #1a1a1a;

  --dress-page-bg: #17181a;
  --dress-head-bg: #17181a;
  --dress-sheet-bg: #1e1f22;
  --dress-row-bg: #1e1f22;
  --dress-title-fg: #9aa0a8;
  --dress-name-fg: #d6d9de;
  --dress-preview-fg: #8b9099;
  --dress-ava-bg: #2c2e33;
  --dress-ava-ring: #1e1f22;
}

/* ========== B. 页面壳 / 顶栏 ========== */
.chat-app {
  background: var(--dress-page-bg);
}
.chat-inbox {
  padding-top: 2px;
}
.chat-head,
.chat-head-inbox {
  background: var(--dress-head-bg);
  border-bottom: none;
}
.chat-inbox-top {
  background: transparent;
}

/* 顶栏标题：藏掉“消息”，改英文 Calendar，灰、加粗，位置不动 */
.chat-inbox-title {
  font-family: "Calendar", Georgia, "Times New Roman", serif;
  font-weight: 800;
  letter-spacing: 0.5px;
  font-size: 0;
}
.chat-inbox-title::after {
  content: "Calendar";
  font-size: 1.375rem;
  line-height: 1.2;
  color: var(--dress-title-fg);
}

.chat-inbox-filter {
}
.chat-inbox-filter button {
}
.chat-inbox-filter button.on {
}

/* ========== C. 表体 ========== */
.chat-list-sheet {
  position: relative;
  border-radius: var(--dress-list-sheet-radius);
  overflow: visible;
  background: var(--dress-sheet-bg);
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.04);
  margin-top: 136px;
}

/* 列表正上方：三个圆形头像（用你给的图片，mask 裁圆） */
.chat-list-sheet::before {
  content: "";
  position: absolute;
  left: 50%;
  bottom: 100%;
  margin-left: -95px;              /* 总宽 190 的一半，居中 */
  margin-bottom: 60px;
  width: 190px;                    /* 54 + 14 + 54 + 14 + 54 */
  height: 54px;

  /* 三张图，各自定位 */
  background-image:
    var(--dress-ava-img-1),
    var(--dress-ava-img-2),
    var(--dress-ava-img-3);
  background-size: 54px 54px, 54px 54px, 54px 54px;
  background-position: 0 0, 68px 0, 136px 0;
  background-repeat: no-repeat;
  background-color: #000;          /* 图加载前的占位黑 */

  /* 裁成三个圆 */
  -webkit-mask:
    radial-gradient(circle 27px at 27px 27px, #000 99%, transparent 100%),
    radial-gradient(circle 27px at 95px 27px, #000 99%, transparent 100%),
    radial-gradient(circle 27px at 163px 27px, #000 99%, transparent 100%);
  -webkit-mask-composite: source-over;
  mask:
    radial-gradient(circle 27px at 27px 27px, #000 99%, transparent 100%),
    radial-gradient(circle 27px at 95px 27px, #000 99%, transparent 100%),
    radial-gradient(circle 27px at 163px 27px, #000 99%, transparent 100%);
  mask-composite: add;

  /* 细白描边 */
  filter:
    drop-shadow(0 1px 0 #fff)
    drop-shadow(0 -1px 0 #fff)
    drop-shadow(1px 0 0 #fff)
    drop-shadow(-1px 0 0 #fff);

  pointer-events: none;
}

/* 外置分组标题：随对话框一起下移，紧贴卡片左上方 */
.chat-list-sheet::after {
  position: absolute;
  bottom: 100%;
  left: 4px;
  margin-bottom: 12px;
  font-size: 13px;
  font-weight: bold;
  color: var(--dress-title-fg);
  letter-spacing: 0.5px;
  z-index: 1;
  pointer-events: none;
}

/* 情况 A：第一个会话是置顶（好友）→ 显示好友分组标题 */
.chat-list-sheet:has(.chat-row-wrap:first-child.is-pinned)::after {
  content: "ᯠ_   ̫ _ ̥ᯄ ੭intimate";
}

/* 情况 B：第一个会话不是置顶（全是 NPC）→ 直接显示 NPC 标题 */
.chat-list-sheet:has(.chat-row-wrap:first-child:not(.is-pinned))::after {
  content: "⬮ ω ⬮NPC";
}

.chat-scroll {
}

/* ========== D. 会话行 ========== */
.chat-row-wrap {
}

/* 情况 C：既有置顶又有普通行 → 在第一个非置顶（NPC）行上方插入 NPC 分组标题 */
.chat-row-wrap.is-pinned + .chat-row-wrap:not(.is-pinned)::before {
  content: "⬮ ω ⬮NPC";
  display: block;
  padding: 16px var(--dress-list-row-pad-x) 8px;
  font-size: 12px;
  font-weight: 600;
  color: var(--dress-title-fg);
  background: var(--dress-row-bg);
  letter-spacing: 0.5px;
  border-top: 1px solid rgba(0, 0, 0, 0.03);
  pointer-events: none;
}

html[data-theme="dark"] .chat-row-wrap.is-pinned + .chat-row-wrap:not(.is-pinned)::before {
  border-top: 1px solid rgba(255, 255, 255, 0.04);
}

.chat-row-wrap.is-pinned {
}
.chat-row-wrap.is-swiping,
.chat-row-wrap.is-actions-open {
}
.chat-row-slider {
}
.chat-row {
  padding: var(--dress-list-row-pad-y) var(--dress-list-row-pad-x);
  background: var(--dress-row-bg);
}
.chat-row-main {
}
.chat-row-top {
}
.chat-row-top strong {
  font-size: var(--dress-list-name-size);
  color: var(--dress-name-fg);
}
.chat-row-pin-mark {
}
.chat-row-preview {
  font-size: var(--dress-list-preview-size);
  line-height: 1.45;
  color: var(--dress-preview-fg);
}
.chat-row-preview.has-unread {
}
.chat-row-meta {
}
.chat-row-unread {
  background: var(--dress-list-unread-bg);
  color: var(--dress-list-unread-fg);
}
.chat-ava-list {
}

/* ========== E. 侧滑操作 ========== */
.chat-row-actions {
}
.chat-row-action {
}
.chat-row-action.is-pin {
}
.chat-row-action.is-delete {
}

/* ========== F. 空态 / 底栏 Tab（可选） ========== */
.chat-zero {
}
.chat-tabdock {
}
.chat-tabdock-pill {
}

snapshot.chatThreadCss:
/* ==========================================================
   Puff · 古早 QQ 奶油粉主题 · 安全整合版
   基于原版工作样式
   原则：保留原生交互；不覆盖心声弹窗；不强制重排页面
   ========================================================== */


/* ========== A. 主题变量 ========== */

.chat-thread {
  --dress-chat-bg-overlay: transparent;

  --dress-header-bg: linear-gradient(
    180deg,
    #fffdfd 0%,
    #fff9fb 52%,
    #fbedf3 100%
  );
  --dress-header-blur: 0px;
  --dress-header-border: #f0dce5;
  --dress-header-radius: 22px;
  --dress-header-shadow:
    0 2px 8px rgba(191,153,170,.08),
    inset 0 1px 0 rgba(255,255,255,.98),
    inset 0 -1px 0 rgba(255,255,255,.72);
  --dress-header-title-color: #9f7e8d;
  --dress-header-title-size: 16px;
  --dress-header-title-weight: 600;
  --dress-header-icon-color: #b99aa9;

  --dress-bubble-me-bg: #fff7fb;
  --dress-bubble-me-fg: #684b5d;
  --dress-bubble-me-border: 1px solid rgba(239,204,223,.78);
  --dress-bubble-me-shadow:
    0 3px 7px rgba(197,135,168,.09),
    inset 0 1px 0 rgba(255,255,255,.98),
    inset 0 -2px 3px rgba(197,135,168,.07);
  --dress-bubble-me-radius: 18px;

  --dress-bubble-them-bg: #f0eff2;
  --dress-bubble-them-fg: #50505b;
  --dress-bubble-them-border: 1px solid rgba(209,207,216,.82);
  --dress-bubble-them-shadow:
    0 3px 8px rgba(106,101,119,.10),
    inset 0 1px 0 rgba(255,255,255,.98),
    inset 0 -2px 3px rgba(112,106,135,.10);
  --dress-bubble-them-radius: 18px;

  --dress-compose-bar-bg: linear-gradient(
    180deg,
    #fffdfd 0%,
    #fff9fb 52%,
    #fbedf3 100%
  );
  --dress-compose-bar-fg: #765365;
  --dress-compose-bar-radius: 999px;
  --dress-compose-bar-border: 1px solid rgba(235,190,211,.75);
  --dress-compose-bar-shadow:
    0 3px 12px rgba(192,130,157,.11),
    inset 0 1px 0 rgba(255,255,255,.98);
  --dress-compose-bar-blur: blur(18px);

  --dress-timestamp-color: #ad91a1;
  --dress-scroll-pad-x: 14px;

  background-color: #fffdfd;
  background-image: linear-gradient(
    180deg,
    #fffdfd 0%,
    #fffafd 45%,
    #fffafd 100%
  );
}


/* ========== B. 暗色模式变量 ========== */

html[data-theme="dark"] .chat-thread {
  --dress-header-bg: linear-gradient(
    180deg,
    #51414b 0%,
    #453641 55%,
    #382d36 100%
  );
  --dress-header-blur: 0px;
  --dress-header-border: rgba(230,184,207,.22);
  --dress-header-shadow:
    0 4px 14px rgba(0,0,0,.24),
    inset 0 1px 0 rgba(255,255,255,.12);
  --dress-header-title-color: #fff0f7;
  --dress-header-icon-color: #f1cfdf;

  --dress-bubble-me-bg: #654657;
  --dress-bubble-me-fg: #fff0f7;
  --dress-bubble-me-border: 1px solid rgba(245,201,223,.22);

  --dress-bubble-them-bg: #393840;
  --dress-bubble-them-fg: #f0edf3;
  --dress-bubble-them-border: 1px solid rgba(220,215,229,.15);

  --dress-compose-bar-bg: linear-gradient(
    180deg,
    #51414b 0%,
    #453641 55%,
    #382d36 100%
  );
  --dress-compose-bar-fg: #fff0f7;
  --dress-compose-bar-border: 1px solid rgba(245,201,223,.18);
  --dress-compose-bar-shadow: 0 4px 14px rgba(0,0,0,.22);

  --dress-timestamp-color: rgba(244,218,233,.65);

  background-color: #29232b;
  background-image: linear-gradient(
    180deg,
    #29232b 0%,
    #29232b 100%
  );
}


/* ========== C. 页面背景与安全区 ========== */

html,
body {
  background-color: #fffdfd;
}

html[data-theme="dark"],
html[data-theme="dark"] body {
  background-color: #29232b;
}

/* 安全区装饰只绘制在对话容器，不触碰弹窗 */
.chat-thread::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: env(safe-area-inset-top, 0px);
  background: #fffdfd;
  pointer-events: none;
  z-index: 0;
}

html[data-theme="dark"] .chat-thread::before {
  background: #29232b;
}


/* ========== D. 顶栏：保留原版结构与背景机制 ========== */

/* 不再把顶栏改成透明背景，不使用全屏宽度伪元素 */
.chat-thread-pill {
  background: var(--dress-header-bg);
  border: 1px solid var(--dress-header-border);
  border-radius: var(--dress-header-radius);
  box-shadow: var(--dress-header-shadow);
  color: var(--dress-header-icon-color);

  -webkit-backdrop-filter: blur(var(--dress-header-blur));
  backdrop-filter: blur(var(--dress-header-blur));
}

.chat-thread-pill .chat-back,
.chat-thread-pill-detail .chat-back,
.chat-back-wrap {
  color: var(--dress-header-icon-color);
}

.chat-thread-center h2 {
  color: var(--dress-header-title-color);
  font-size: var(--dress-header-title-size);
  font-weight: var(--dress-header-title-weight);
}

.chat-thread-head-more,
.chat-thread-head-xinsheng {
  color: var(--dress-header-icon-color);
}

/*
  对话设置顶栏与聊天顶栏分开处理。
  不对 .chat-thread-pill-detail 强行设置背景、
  定位、透明度或伪元素，避免影响其他界面。
*/


/* ========== E. 消息滚动区 ========== */

.chat-thread-scroll {
  scrollbar-width: thin;
  scrollbar-color: rgba(222,174,197,.3) transparent;
}


/* ========== F. 消息行与头像 ========== */

.chat-msg {
  margin-bottom: 10px;
}

.chat-ava,
.chat-ava-sm {
  box-sizing: border-box;
  border-radius: 50%;
  border: 2px solid rgba(255,255,255,.96);
  outline: 1px solid rgba(229,188,207,.82);
  outline-offset: 2px;
  background-color: #fff8fb;
  box-shadow:
    0 0 0 3px rgba(255,247,251,.92),
    0 2px 8px rgba(180,132,155,.13);
}

.chat-ava-sm {
  border-width: 1.5px;
  outline-offset: 1px;
  box-shadow:
    0 0 0 2px rgba(255,247,251,.9),
    0 2px 5px rgba(180,132,155,.11);
}

.chat-msg-name {
  font-size: 11px;
  color: #a8879a;
  opacity: .88;
}


/* ========== G. 核心气泡 ========== */

.chat-bubble {
  box-sizing: border-box;
  line-height: 1.5;
  padding: 5px 12px;
  border-radius: 18px;
  overflow-wrap: anywhere;
  background-clip: padding-box;
  transition: box-shadow .22s ease, background .22s ease;
}

.chat-msg.is-me .chat-bubble,
.chat-bubble-primary.is-me {
  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,.98) 0%,
      rgba(255,255,255,.55) 16%,
      rgba(255,255,255,.12) 38%,
      rgba(237,197,219,.035) 72%,
      rgba(225,185,211,.10) 100%
    ),
    linear-gradient(
      135deg,
      #fffefe 0%,
      #fff9fc 34%,
      #fff2f8 70%,
      #fceefa 100%
    );
  color: #684b5d;
  border: 1px solid rgba(239,204,223,.82);
  border-radius: 18px;
  box-shadow:
    0 3px 7px rgba(178,108,148,.09),
    0 1px 2px rgba(159,94,130,.05),
    inset 0 1.5px 0 rgba(255,255,255,1),
    inset 1px 0 0 rgba(255,255,255,.85),
    inset -1px 0 0 rgba(255,255,255,.65),
    inset 0 -2px 3px rgba(190,116,157,.07);
}

.chat-msg.is-them .chat-bubble {
  background:
    linear-gradient(
      180deg,
      rgba(255,255,255,.98) 0%,
      rgba(255,255,255,.52) 14%,
      rgba(255,255,255,.06) 38%,
      rgba(139,135,155,.07) 78%,
      rgba(133,128,151,.16) 100%
    ),
    linear-gradient(
      135deg,
      #fff 0%,
      #f6f5f9 32%,
      #e8e7ef 68%,
      #f4f1f7 100%
    );
  color: #50505b;
  border: 1px solid rgba(207,203,218,.95);
  border-radius: 18px;
  box-shadow:
    0 4px 8px rgba(93,87,113,.12),
    0 1px 2px rgba(88,81,105,.08),
    inset 0 1.5px 0 rgba(255,255,255,1),
    inset 1px 0 0 rgba(255,255,255,.78),
    inset -1px 0 0 rgba(255,255,255,.45),
    inset 0 -2px 3px rgba(112,106,135,.12);
}

/* 气泡顶部高光 */
.chat-msg.is-me .chat-bubble::before,
.chat-msg.is-them .chat-bubble::before {
  content: "";
  position: absolute;
  top: 1px;
  left: 9px;
  right: 9px;
  height: 40%;
  border-radius: 16px 16px 50% 50%;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,.65) 0%,
    rgba(255,255,255,.2) 40%,
    rgba(255,255,255,0) 100%
  );
  pointer-events: none;
}

.chat-bubble--bilingual {
  padding-top: 5px;
  padding-bottom: 5px;
  border-radius: 17px;
}

.chat-msg.is-me .chat-bubble--bilingual {
  background: linear-gradient(145deg, #fffefe, #fff3f9);
  border: 1px solid rgba(239,204,223,.78);
  box-shadow:
    0 3px 7px rgba(178,108,148,.08),
    inset 0 1px 0 rgba(255,255,255,.98),
    inset 0 -2px 3px rgba(190,116,157,.06);
}

.chat-msg.is-them .chat-bubble--bilingual {
  background: linear-gradient(145deg, #fff, #efedf2);
  border: 1px solid rgba(209,207,216,.85);
  box-shadow:
    0 3px 7px rgba(93,87,113,.10),
    inset 0 1px 0 rgba(255,255,255,1),
    inset 0 -2px 3px rgba(112,106,135,.10);
}

.chat-bubble--trans-tap {
  border-radius: 17px;
}

.chat-bubble-trans-rule {
  border-color: rgba(185,165,180,.25);
}

.chat-bubble-trans-inline {
  color: #8f8290;
}

.chat-bubble-trans-chip {
  background: rgba(243,224,235,.8);
  border: 1px solid rgba(229,190,210,.65);
  border-radius: 999px;
  color: #966c83;
}

.chat-bubble-trans-chip-label {
  color: #a27e92;
}


/* ========== H. 时间戳与通知 ========== */

.chat-msg-time,
.chat-msg-timestamp {
  color: var(--dress-timestamp-color);
  font-size: 11px;
}

.chat-thread-notice {
  color: #a98d9f;
}

.chat-thread-notice.is-tap {
  color: #bf86a2;
}

.chat-thread-notice-hint {
  color: #c2a8b7;
}


/* ========== I. 引用与撤回 ========== */

.chat-qq-quote {
  background: linear-gradient(
    180deg,
    rgba(241,240,243,.95),
    rgba(231,229,235,.95)
  );
  border: 1px solid rgba(218,214,224,.68);
  border-radius: 15px;
  color: #8a8591;
  box-shadow: inset 0 1px 0 rgba(255,255,255,.85);
}

.chat-qq-quote.is-tap {
  background: linear-gradient(180deg, #f5eaf0, #f0e2eb);
}

.chat-qq-quote-name {
  color: #9c8092;
}

.chat-qq-quote-text {
  color: #88828e;
}

.chat-recall-text {
  color: #b39aaa;
}

.chat-recall-view {
  color: #c18ba6;
}


/* ========== J. 推演提示 ========== */

.chat-thinking-chip {
  background: rgba(250,236,244,.95);
  border: 1px solid rgba(231,196,214,.7);
  border-radius: 999px;
  color: #a47d93;
}


/* ========== K. 语音 ========== */

.puff-voice-pill {
  background: linear-gradient(145deg, #fffafd, #f5e7ef);
  border: 1px solid rgba(230,191,211,.7);
  border-radius: 20px;
  box-shadow: 0 3px 8px rgba(190,135,162,.1);
  color: #78596c;
}

.puff-voice-waves,
.puff-voice-wave {
  color: #c68eaa;
}

.puff-voice-glyph {
  color: #bd86a1;
}

.puff-voice-dur {
  color: #9e8294;
}

.puff-voice-note {
  background: rgba(255,247,251,.9);
  border-radius: 16px;
}

.puff-voice-note-body {
  color: #725a6a;
}

.puff-voice-note-tr {
  color: #9a8695;
}


/* ========== L. 表情与图片 ========== */

.chat-bubble-sticker {
  border-radius: 18px;
}

.puff-photo {
  border-radius: 15px;
  box-shadow: 0 3px 10px rgba(170,130,150,.12);
}


/* ========== M. 反应与卡片消息 ========== */

.chat-reaction-chip {
  background: rgba(255,247,251,.96);
  border: 1px solid rgba(232,195,214,.75);
  border-radius: 999px;
  box-shadow: 0 2px 6px rgba(190,135,162,.08);
}

.chat-reaction-chip-meta {
  color: #a58b9b;
}

.puff-transfer,
.puff-gift,
.puff-diary-share,
.puff-forum-share {
  border-radius: 20px;
  border: 1px solid rgba(232,195,214,.7);
  box-shadow: 0 3px 10px rgba(190,135,162,.1);
}


/* ========== N. 气泡操作板 ========== */

.chat-msg-multi-action {
  color: #946e83;
}

.chat-bubble-actions-card {
  background: rgba(255,250,253,.98);
  border: 1px solid rgba(232,195,214,.75);
  border-radius: 18px;
  box-shadow: 0 6px 20px rgba(180,125,151,.15);
}

.chat-bubble-actions-item {
  color: #765365;
}


/* ========== O. 输入栏：只调整外观，不重排结构 ========== */

/* 不给 .chat-compose 外层强制加背景或高度 */
.chat-thread .chat-compose-bar {
  background: var(--dress-compose-bar-bg);
  color: var(--dress-compose-bar-fg);
  border: var(--dress-compose-bar-border);
  border-radius: var(--dress-compose-bar-radius);
  box-shadow: var(--dress-compose-bar-shadow);

  -webkit-backdrop-filter: var(--dress-compose-bar-blur);
  backdrop-filter: var(--dress-compose-bar-blur);
}

/* 输入框使用珍珠白配色，保留原有尺寸和布局 */
.chat-thread .chat-compose-input {
  background: linear-gradient(
    180deg,
    #ffffff 0%,
    #fffefe 56%,
    #fffafd 100%
  );
  border: 1px solid #efd9e4;
  border-radius: 999px;
  color: #765365;
  box-shadow:
    0 2px 4px rgba(185,135,157,.07),
    inset 0 1px 0 rgba(255,255,255,1),
    inset 0 -1px 0 rgba(245,224,234,.55);
}

.chat-thread .chat-compose-input::placeholder {
  color: #bba2b0;
}

/* 原生按钮仅改颜色，不改宽高、定位与点击区域 */
.chat-compose-plus,
.chat-compose-icon,
.chat-compose-icon.is-voice,
.chat-compose-icon.is-reply {
  color: #a77f94;
}

.chat-compose-icon.is-send.ready {
  color: #bd7899;
}


